-- =========================================================================
-- Seed 32 : quizzes for Python for Data Science
--
-- One per level, the last one an exam over the whole course. Generated by
-- the shared builder, which refuses to emit a single_choice without exactly
-- one correct option, or a multiple_choice with fewer than two.
-- =========================================================================

INSERT INTO assessment_quizzes
  (id, course_id, lesson_id, title, description, pass_percent, time_limit_seconds,
   max_attempts, shuffle_questions, shuffle_options, show_answers, status)
VALUES
  ('f0000001-0000-4000-8000-000000000034',
   'c0000001-0000-4000-8000-000000000010', 'e0000001-0000-4000-8000-0000000000d4',
   'Level 1 Check: Arrays and DataFrames',
   'Vectorised thinking, the axis argument, dtypes and the difference between loc and iloc.',
   60, 600, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-000000000035',
   'c0000001-0000-4000-8000-000000000010', 'e0000001-0000-4000-8000-0000000000d8',
   'Level 2 Check: Loading, Cleaning and Reshaping',
   'Awkward files, what a gap in the data means, and the join that doubles your row count.',
   60, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-000000000036',
   'c0000001-0000-4000-8000-000000000010', 'e0000001-0000-4000-8000-0000000000dc',
   'Level 3 Check: Grouping, Time and Charts',
   'Transform against agg, what resample does to an empty day, which way tz_localize goes, and which chart answers which question.',
   70, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-000000000037',
   'c0000001-0000-4000-8000-000000000010', 'e0000001-0000-4000-8000-0000000000e0',
   'Expert Exam: Python for Data Science',
   'Memory and dtypes, reproducibility, idempotence, and knowing when the answer is a database rather than a bigger machine.',
   70, 1500, 3, 1, 1, 1, 'published')
ON DUPLICATE KEY UPDATE
  title = VALUES(title), description = VALUES(description),
  pass_percent = VALUES(pass_percent), status = VALUES(status);

INSERT INTO assessment_questions
  (id, quiz_id, kind, prompt, explanation, points, `position`, correct_text)
VALUES
  -- Level 1 Check: Arrays and DataFrames
  ('a1000001-0000-4000-8000-000000000301', 'f0000001-0000-4000-8000-000000000034', 'single_choice',
   'Why is prices * 1.2 faster than looping over the list and multiplying each item?',
   'The array is one typed block of memory, so the multiplication runs as a tight loop in compiled C with no Python interpreter in it. The loop version executes a million interpreter steps and allocates a million objects.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000302', 'f0000001-0000-4000-8000-000000000034', 'single_choice',
   'grid has shape (3, 4). What does grid.sum(axis=0) return?',
   'Four values, one per column. axis is the axis that disappears: axis=0 collapses the rows, leaving one value for each of the four columns.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-000000000303', 'f0000001-0000-4000-8000-000000000034', 'single_choice',
   'A DataFrame has been filtered and sorted. What is the difference between df.loc[0] and df.iloc[0]?',
   'loc looks up the index LABEL 0, which after sorting may be anywhere or absent entirely; iloc takes the first row by POSITION. With a fresh default index the two agree, which is why the difference is usually discovered the hard way.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-000000000304', 'f0000001-0000-4000-8000-000000000034', 'multiple_choice',
   'Which of these are reasons to run df.info() on data you have just loaded? Select all that apply.',
   'info() shows dtypes, non-null counts and memory in one screen. A numeric column that arrived as object and a column full of nulls are both things you want to know before computing anything, and both are visible there.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-000000000305', 'f0000001-0000-4000-8000-000000000034', 'single_choice',
   'What is pandas telling you with SettingWithCopyWarning?',
   'It cannot tell whether the object you are assigning to is a view onto the original frame or a copy of it, so it cannot tell whether your assignment will reach the original. Use .copy() when you want a separate frame, or .loc on the original when you mean to change it.',
   2, 5, NULL),

  -- Level 2 Check: Loading, Cleaning and Reshaping
  ('a1000001-0000-4000-8000-000000000306', 'f0000001-0000-4000-8000-000000000035', 'single_choice',
   'A CSV exported from a European system fails to parse: the numbers all land in one column. What is the most likely cause?',
   'The file is semicolon separated, because the comma is being used as the decimal point. sep=";" and often decimal="," are what read_csv needs. An encoding problem raises a UnicodeDecodeError instead, which looks quite different.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000307', 'f0000001-0000-4000-8000-000000000035', 'multiple_choice',
   'A numeric column contains 9999 where a reading was not taken. Why is this worse than an empty cell? Select all that apply.',
   'isna() does not see it, so no missing-value check catches it, and it is a plausible magnitude so it does not look wrong in a sample. It is also included in every mean, max and sum, which is how it changes an answer without raising anything.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-000000000308', 'f0000001-0000-4000-8000-000000000035', 'single_choice',
   'What does errors="coerce" do in pd.to_numeric?',
   'Values that cannot be parsed become NaN instead of raising. That is usually what you want - followed immediately by counting how many it produced, because that count is the size of your parsing problem.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-000000000309', 'f0000001-0000-4000-8000-000000000035', 'single_choice',
   'After a left merge your row count has gone up. What happened?',
   'The right-hand frame had more than one row for a key, so every matching left row was duplicated once per match. validate="many_to_one" would have raised instead of multiplying, and an assertion on the row count catches the rest.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-00000000030a', 'f0000001-0000-4000-8000-000000000035', 'single_choice',
   'In a filter, why is df[(df.a > 1) & (df.b < 2)] correct where df[df.a > 1 and df.b < 2] is not?',
   'and needs a single true or false, and a Series of booleans is neither - it raises. & combines two boolean Series element by element. The brackets are needed because & binds more tightly than the comparisons.',
   2, 5, NULL),

  -- Level 3 Check: Grouping, Time and Charts
  ('a1000001-0000-4000-8000-00000000030b', 'f0000001-0000-4000-8000-000000000036', 'single_choice',
   'What is the difference between groupby().agg() and groupby().transform()?',
   'agg returns one row per group. transform returns a result the same length as the input, aligned to the original index - which is how you put a group total next to every row that contributed to it.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-00000000030c', 'f0000001-0000-4000-8000-000000000036', 'single_choice',
   'Your data has no rows for 3 January. What does resample("D").sum() do with that day?',
   'It appears in the output with 0. resample builds a regular time index and fills the gaps, which is why it is the right tool for totals and charts - a missing day that silently vanishes becomes a line drawn straight across it.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-00000000030d', 'f0000001-0000-4000-8000-000000000036', 'single_choice',
   'Your timestamps are naive and you know they are UTC. Which call is correct?',
   'tz_localize attaches a zone to naive timestamps - it states what they always meant. tz_convert moves already-aware timestamps to another zone. Using convert on naive data raises; using localize on the wrong zone shifts every value silently.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-00000000030e', 'f0000001-0000-4000-8000-000000000036', 'multiple_choice',
   'Why plot a histogram of a column you have already described with mean and standard deviation? Select all that apply.',
   'A mean of 17 is consistent with every value being 17, with a split between 4 and 30, and with a long tail of outliers. Those want different decisions, and the histogram tells them apart at a glance.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-00000000030f', 'f0000001-0000-4000-8000-000000000036', 'single_choice',
   'Which chart type is the wrong choice for a daily sales figure over two years?',
   'A bar chart per day throws away the continuity that is the whole point of a time series, and at 730 bars it is unreadable. A line shows trend and seasonality immediately.',
   2, 5, NULL),

  -- Expert Exam: Python for Data Science
  ('a1000001-0000-4000-8000-000000000310', 'f0000001-0000-4000-8000-000000000037', 'single_choice',
   'A DataFrame with four distinct region values over a million rows uses far more memory than expected. What is the single most effective fix?',
   'Convert the column to category. Four distinct strings over a million rows is stored as a million pointers to strings; as a category it is four strings and a million small integers. Downcasting numeric columns helps too, usually less.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000311', 'f0000001-0000-4000-8000-000000000037', 'single_choice',
   'Why does memory_usage() need deep=True to be useful?',
   'Without it, object columns report the size of the pointers rather than of the strings they point at - so the column whose memory you are worried about is the one it under-reports.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-000000000312', 'f0000001-0000-4000-8000-000000000037', 'multiple_choice',
   'Your analysis gives different numbers on a colleague machine. Which of these are plausible causes? Select all that apply.',
   'All but the last. An unpinned library can change a default between versions, an unseeded sample differs every run, and notebook cells run out of order produce state that does not exist on a clean start. Reading the same file is the one thing that is usually fine - unless the file itself changed, which is why hashing it is worth the line.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-000000000313', 'f0000001-0000-4000-8000-000000000037', 'single_choice',
   'Why must a scheduled job be idempotent?',
   'Schedulers retry, often without telling you. A job that appends rather than replacing or upserting will silently double a period on a retry, and the error shows up as a number nobody can explain rather than as a failure.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-000000000314', 'f0000001-0000-4000-8000-000000000037', 'single_choice',
   'Ten million rows live in a database and you need the weekly total per region. What is the first thing to try?',
   'Do the filtering and grouping in SQL and bring back the summary. The database has indexes and was built for exactly this; loading ten million rows to produce fifty is the expensive way round. Chunking and Polars are later answers, for when the work genuinely has to happen in Python.',
   2, 5, NULL),

  ('a1000001-0000-4000-8000-000000000315', 'f0000001-0000-4000-8000-000000000037', 'single_choice',
   'Which of these is the strongest evidence that an analysis is reproducible?',
   'Restart the kernel and run every cell from the top, on a clean environment built from pinned versions. Everything else is an opinion about the code; this is a test of it.',
   2, 6, NULL)
ON DUPLICATE KEY UPDATE
  prompt = VALUES(prompt), explanation = VALUES(explanation), points = VALUES(points);

-- Options are inserted rather than replaced, for the reason seed 14 gives:
-- deleting and re-inserting them would orphan every answer already recorded
-- against them, and a graded attempt whose answers point at nothing is a
-- review that resolves nothing.
INSERT INTO assessment_question_options (question_id, body, is_correct, `position`)
SELECT v.question_id, v.body, v.is_correct, v.pos
  FROM (
    SELECT 'a1000001-0000-4000-8000-000000000301' AS question_id, 'The arithmetic runs in compiled code over a typed block of memory' AS body, 1 AS is_correct, 1 AS pos
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000301', 'NumPy caches the result of the multiplication', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000301', 'Python optimises multiplication by constants automatically', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000301', 'The loop version is wrong, so the comparison is unfair', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000302', 'An array of 4 values, one per column', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000302', 'An array of 3 values, one per row', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000302', 'A single number, the total of everything', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000302', 'An array of shape (3, 4) with running totals', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000303', 'loc selects by index label, iloc by position', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000303', 'They are the same; iloc is just older', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000303', 'loc selects a row, iloc selects a column', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000303', 'loc copies, iloc returns a view', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000304', 'It shows a column that loaded as object when you expected a number', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000304', 'It shows how many non-null values each column has', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000304', 'It shows the memory the frame is using', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000304', 'It fixes the dtypes it finds to be wrong', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000305', 'It cannot tell whether your assignment will reach the original frame', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000305', 'The frame is too large to copy safely', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000305', 'The column you assigned to does not exist yet', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000305', 'You are assigning a value of the wrong dtype', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000306', 'It is semicolon separated, because the comma is the decimal point', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000306', 'The file is in UTF-16 and needs an encoding argument', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000306', 'The header row is missing', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000306', 'pandas cannot read files produced outside Python', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000307', 'isna() does not report it, so the usual checks miss it', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000307', 'It is included in the mean, the max and the total', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000307', 'It looks like a plausible value when you scan the data', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000307', 'pandas refuses to compute statistics on columns containing it', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000308', 'Unparseable values become NaN rather than raising', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000308', 'It rounds values that are not whole numbers', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000308', 'It silently drops rows that cannot be parsed', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000308', 'It retries parsing with a different locale', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000309', 'The right-hand frame had several rows per key', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000309', 'A left merge always adds rows for unmatched keys', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000309', 'The join columns had different dtypes', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000309', 'The index was not reset before merging', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030a', 'and cannot operate on a Series of booleans; & combines them element by element', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030a', 'and is slower but otherwise equivalent', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030a', 'and only works on numeric columns', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030a', 'There is no difference; both forms work', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030b', 'agg returns one row per group; transform returns one value per original row', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030b', 'transform is the lazy version and must be collected', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030b', 'agg works on numbers only; transform works on strings too', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030b', 'They are the same; transform is the older name', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030c', 'It appears in the result with a value of 0', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030c', 'It is left out, exactly as groupby would leave it out', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030c', 'It raises, because the series is not continuous', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030c', 'It is filled with the previous day value', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030d', 'tz_localize("UTC"), then tz_convert to display elsewhere', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030d', 'tz_convert("UTC"), then tz_localize to display elsewhere', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030d', 'Either, they do the same thing', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030d', 'Neither; naive timestamps cannot be given a zone', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030e', 'Very different distributions can share a mean', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030e', 'Outliers and a long tail are visible in a way summary statistics hide', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030e', 'It shows whether the data is bimodal', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030e', 'It computes the standard deviation more accurately', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030f', 'A bar chart with one bar per day', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030f', 'A line chart with the date on the x axis', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030f', 'A line chart of a 7-day rolling mean', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000030f', 'A bar chart of monthly totals', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000310', 'Convert the repeated string column to category dtype', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000310', 'Convert every float64 column to float32', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000310', 'Reset the index to free the old one', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000310', 'Call gc.collect() after loading', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000311', 'Object columns otherwise report pointer size, not the strings themselves', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000311', 'It includes the index, which is otherwise excluded', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000311', 'It reports in megabytes rather than bytes', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000311', 'It accounts for memory the garbage collector has not reclaimed', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000312', 'Library versions are not pinned and a default changed', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000312', 'A sample or split has no fixed random seed', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000312', 'Cells were run out of order and the notebook has hidden state', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000312', 'Reading a CSV is non-deterministic', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000313', 'Because retries happen, and an appending job doubles its output', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000313', 'Because the scheduler runs jobs in parallel by default', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000313', 'Because Parquet files cannot be appended to', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000313', 'Because pandas caches results between runs', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000314', 'Group in SQL and read back the summary', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000314', 'Read it all with chunksize and aggregate the chunks', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000314', 'Switch to Polars', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000314', 'Downcast the dtypes and load it all', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000315', 'It runs top to bottom from a restarted kernel in a pinned environment', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000315', 'Every cell has a comment explaining what it does', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000315', 'It was reviewed by a colleague', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000315', 'The final numbers match last month', 0, 4
  ) v
ON DUPLICATE KEY UPDATE
  body = VALUES(body), is_correct = VALUES(is_correct);

CALL catalog_refresh_course_rollup('c0000001-0000-4000-8000-000000000010');
CALL search_reindex_all_quiet();
